#!/usr/local/bin/python3
"""Assemble computations.json: every script, command, interpreter version and
raw output, embedded as text (BD-7, deliverable 2). Standard library only.
Usage: assemble.py ASSEMBLED_AT
"""
import hashlib
import json
import os
import subprocess
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
SCRATCH = "<scratch> = <session scratchpad>/BATCH-4708f7/TASK-20261002-c81b2e"


def rd(name):
    with open(os.path.join(HERE, name)) as fh:
        return fh.read()


def sha(name):
    with open(os.path.join(HERE, name), "rb") as fh:
        return hashlib.sha256(fh.read()).hexdigest()


def captured(name):
    return {
        "stdout": rd(name + ".stdout.txt"),
        "stderr": rd(name + ".stderr.txt"),
        "exit_code": int(rd(name + ".exit.txt").strip()),
    }


ver = subprocess.run(["/usr/local/bin/python3", "--version"], capture_output=True, text=True)

doc = {
    "task_id": "TASK-20261002-c81b2e",
    "joints_owned": ["JD3"],
    "assembled_at": sys.argv[1],
    "scratch_directory": SCRATCH,
    "interpreter": {
        "path": "/usr/local/bin/python3",
        "version_command": "/usr/local/bin/python3 --version",
        "version_command_stdout": ver.stdout,
        "version_command_stderr": ver.stderr,
        "sys_version": sys.version,
    },
    "libraries": {
        "computation": "Python standard library only",
        "parse_check_only": "PyYAML 6.0.1 (/usr/lib/python3/dist-packages/yaml), imported by check.py only; computes no reported value",
    },
    "environment": {
        "PYTHONDONTWRITEBYTECODE": "set to 1 for emit_report.py v3, check.py (final) and assemble.py; earlier runs created no bytecode file (checked, see commands C7)",
    },
    "scripts": [],
    "commands": [],
    "raw_outputs": {},
    "report": {},
    "notes": [],
}

for name in ("rederive.py", "emit_report.py", "check.py", "assemble.py"):
    doc["scripts"].append({"name": name, "sha256": sha(name), "text": rd(name)})

C = doc["commands"]
C.append({
    "id": "C1", "capture": "transcribed verbatim from the session's tool result (run before file capture was set up)",
    "command": "wc -l /home/user/crypto-autoresearcher/AGENTS.md /home/user/crypto-autoresearcher/agents/validator.md /home/user/crypto-autoresearcher/templates/research-records.md; ls -la <scratch>",
    "exit_code": 0,
    "stdout": "  914 /home/user/crypto-autoresearcher/AGENTS.md\n  166 /home/user/crypto-autoresearcher/agents/validator.md\n  725 /home/user/crypto-autoresearcher/templates/research-records.md\n 1805 total\ntotal 8\ndrwxr-xr-x 2 root root 4096 Oct  2 13:43 .\ndrwxr-xr-x 6 root root 4096 Oct  2 13:43 ..\n",
    "stderr": "",
})
C.append({
    "id": "C2", "capture": "transcribed verbatim from the session's tool result",
    "command": "/usr/local/bin/python3 --version; /usr/local/bin/python3 -c \"import sys,platform; print(sys.version); print(platform.python_implementation(), platform.python_version()); print(sys.executable)\"; /usr/local/bin/python3 -c \"import yaml; print('PyYAML', yaml.__version__, yaml.__file__)\" 2>&1; date -u +%Y-%m-%dT%H:%M:%SZ",
    "exit_code": 0,
    "stdout": "Python 3.11.15\n3.11.15 (main, Mar  3 2026, 09:26:23) [GCC 13.3.0]\nCPython 3.11.15\n/usr/local/bin/python3\nPyYAML 6.0.1 /usr/lib/python3/dist-packages/yaml/__init__.py\n2026-10-02T13:47:07Z\n",
    "stderr": "",
})
C.append({
    "id": "C3", "capture": "files attempt1_usr_bin_time.{stderr,exit}.txt; stdout file was empty and removed",
    "command": "cd <scratch> && /usr/bin/time -v /usr/local/bin/python3 rederive.py > rederive.stdout.txt 2> rederive.stderr.txt; echo $? > rederive.exit.txt",
    "exit_code": int(rd("attempt1_usr_bin_time.exit.txt").strip()),
    "stdout": "",
    "stderr": rd("attempt1_usr_bin_time.stderr.txt"),
    "outcome": "failed attempt: /usr/bin/time is not installed, so rederive.py did not run. Retained as a failed attempt; it is not a result.",
})
c4 = {
    "id": "C4", "capture": "files rederive.{stdout,stderr,exit,time,started}.txt",
    "command": "cd <scratch> && { TIMEFORMAT='real %R s, user %U s, sys %S s'; time /usr/local/bin/python3 rederive.py > rederive.stdout.txt 2> rederive.stderr.txt; echo $? > rederive.exit.txt; } 2> rederive.time.txt",
    "started_at": rd("rederive.started.txt").strip(),
    "time": rd("rederive.time.txt").strip(),
}
c4.update(captured("rederive"))
C.append(c4)
C.append({
    "id": "C5", "capture": "superseded; outputs overwritten in scratch",
    "command": "cd <scratch> && /usr/local/bin/python3 emit_report.py \"$TS\" > emit_report.stdout.txt 2> emit_report.stderr.txt",
    "exit_code": 0,
    "outcome": "emit_report.py v1. Its double-rounding note claimed every listed row would move UP by 0.01, which is wrong for (L3, 5) and (L8, 7) under a half-even second step. The script was corrected to compute and print both second-step variants per row. No computed Q value changed, since all come from results.json, produced once by C4.",
})
C.append({
    "id": "C6", "capture": "superseded; outputs overwritten in scratch",
    "command": "cd <scratch> && /usr/local/bin/python3 emit_report.py \"$TS\" ... ; /usr/local/bin/python3 check.py rederivation-report.yaml results.json results.json",
    "exit_code": 0,
    "outcome": "emit_report.py v2 and check.py, which passed. Two prose wording fixes followed (sources_read_note, header comment). No value changed.",
})
C.append({
    "id": "C7", "capture": "summary of the session tool result",
    "command": "ls -la --time-style=full-iso /usr/lib/python3/dist-packages/yaml/__pycache__/ | head -30; find /usr/local/lib/python3.11 -name '*.pyc' -newer <scratch>/rederive.py",
    "exit_code": 0,
    "outcome": "All yaml cpython-311 .pyc files are dated 2026-09-26, before this task. No stdlib .pyc is newer than rederive.py. No bytecode file was written by this task.",
})
c8 = {
    "id": "C8", "capture": "files emit_report.{stdout,stderr,exit}.txt, emit.ts.txt",
    "command": "cd <scratch> && TS=$(date -u +%Y-%m-%dT%H:%M:%SZ) && echo \"$TS\" > emit.ts.txt && PYTHONDONTWRITEBYTECODE=1 /usr/local/bin/python3 emit_report.py \"$TS\" > emit_report.stdout.txt 2> emit_report.stderr.txt; echo $? > emit_report.exit.txt",
    "argument_TS": rd("emit.ts.txt").strip(),
}
c8.update(captured("emit_report"))
C.append(c8)
c9 = {
    "id": "C9", "capture": "files check.{stdout,stderr,exit}.txt",
    "command": "cd <scratch> && PYTHONDONTWRITEBYTECODE=1 /usr/local/bin/python3 check.py rederivation-report.yaml results.json results.json > check.stdout.txt 2> check.stderr.txt; echo $? > check.exit.txt",
}
c9.update(captured("check"))
C.append(c9)
C.append({
    "id": "C10",
    "command": "cd <scratch> && PYTHONDONTWRITEBYTECODE=1 /usr/local/bin/python3 assemble.py \"$(date -u +%Y-%m-%dT%H:%M:%SZ)\"",
    "outcome": "Produces this file. Its own stdout cannot be embedded here; it is reported in the hand-back.",
})
C.append({
    "id": "C11",
    "command": "mkdir -p -v <write_scope>; cp <scratch>/rederivation-report.yaml <scratch>/computations.json <write_scope>/; sha256sum both; PYTHONDONTWRITEBYTECODE=1 /usr/local/bin/python3 <scratch>/check.py <write_scope>/rederivation-report.yaml <scratch>/results.json <write_scope>/computations.json",
    "outcome": "Install and final parse check, run after this file was assembled; reported in the hand-back.",
})
C.append({
    "id": "C12",
    "command": "(first pass of C11, then) ls -la <write_scope>; edit emit_report.py sources_read_note; repeat C8, C9, C10 and C11",
    "outcome": "The first installation (report sha256 ea113066..., computations sha256 e9ae5244...) passed the final check. The write-scope listing showed the '..' metadata line of the reviews directory. That disclosure was added to sources_read_note, and both files were regenerated and re-installed over this task's own uncommitted outputs before hand-off. No computed value changed. This file describes the second pass.",
})

doc["raw_outputs"] = {
    "results.json": {"sha256": sha("results.json"), "text": rd("results.json")},
    "rederive.stdout.txt": {"sha256": sha("rederive.stdout.txt"), "text": rd("rederive.stdout.txt")},
}
doc["report"] = {
    "path": "coordination/goals/GOAL-ECDLP2M-001/batches/BATCH-4708f7/reviews/TASK-20261002-c81b2e/rederivation-report.yaml",
    "sha256_of_scratch_copy_at_assembly": sha("rederivation-report.yaml"),
    "generated_by": "emit_report.py (C8), from results.json (C4)",
}
doc["notes"] = [
    "Runs launched: 0. No experiment, no network access, no git command.",
    "All reported values come from rederive.py (C4). emit_report.py only formats them, and check.py re-parses the report and re-checks every Q1/Q2/Q3 value against results.json and against an inline recomputation.",
    "The C1 and C2 outputs were captured from the session's tool results, not from files. Their text is reproduced verbatim.",
]

out = os.path.join(HERE, "computations.json")
with open(out, "w") as fh:
    json.dump(doc, fh, indent=1, ensure_ascii=True)
    fh.write("\n")
with open(out) as fh:
    json.load(fh)
print("wrote", out, os.path.getsize(out), "bytes; sha256", sha("computations.json"))
print("report sha256 (scratch):", sha("rederivation-report.yaml"))
